const fs = require('fs');
const path = process.argv[2];
const width = Number(process.argv[3] || 1440);
const wsUrl = process.env.WS;
const ws = new WebSocket(wsUrl);
let id = 0; const pending = new Map(); const errs = [];
ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id) { const p = pending.get(m.id); if (p) { pending.delete(m.id); p(m); } } else { if (m.method === 'Runtime.exceptionThrown' || m.method === 'Log.entryAdded') errs.push(m); } };
const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const delay = ms => new Promise(r => setTimeout(r, ms));
const evalJS = async (expression) => {
  const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (r.result?.exceptionDetails) return { EXCEPTION: r.result.exceptionDetails.text, detail: r.result.exceptionDetails.exception?.description };
  return r.result?.result?.value;
};

ws.onopen = async () => {
  await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable');
  await send('Emulation.setDeviceMetricsOverride', { width, height: 900, deviceScaleFactor: 1, mobile: width < 700 });
  await send('Page.navigate', { url: 'file://' + path });
  await delay(900);

  const snap = `(() => {
    const q = s => document.querySelector(s);
    const toast = q('#toast');
    return {
      focus: document.activeElement?.tagName + ':' + (document.activeElement?.textContent || '').trim().slice(0,40),
      activeClass: document.activeElement?.className,
      toastHidden: toast.hidden,
      toastText: q('#toast-msg').textContent,
      toastVisible: toast.classList.contains('is-visible'),
      undoId: q('#toast-undo').dataset.id,
      careNames: [...document.querySelectorAll('#care-list .care-name button')].map(b => b.textContent),
      settled: [...document.querySelectorAll('.settled-row')].map(r => r.innerText.replace(/\\n+/g,' | ')),
      meter: q('#meter').getAttribute('aria-valuenow'),
      meterWidth: q('#meter-fill').style.width,
      detailStatus: q('.status-pill')?.textContent.trim() || null,
      detailActions: [...document.querySelectorAll('.detail-actions .btn')].map(b=>b.textContent.trim()),
      allDoneHidden: q('#all-done').hidden,
      allDoneTitle: q('#all-done-title').textContent,
      doneCopy: q('#done-copy').textContent,
      receipt: q('#done-receipt').textContent,
      doneUndoHidden: q('#done-undo').hidden,
      weekTotal: q('#week-total').textContent,
      weekLeaves: document.querySelectorAll('.wk-leaf').length,
      weekSat: document.querySelectorAll('.wk-day')[5].querySelectorAll('.wk-leaf').length,
      queueSub: q('#queue-sub').textContent,
      listHidden: q('#care-list').hidden,
      detailPlant: q('#detail-title')?.textContent,
      detailHistory: [...document.querySelectorAll('.tl-item')].map(li=>li.innerText.replace(/\\n+/g,' | ')),
      detailFacts: [...document.querySelectorAll('.fact-value')].map(e=>e.textContent),
      announcer: q('#announcer').textContent
    };
  })()`;

  console.log('STEP 0 initial');
  console.log(JSON.stringify(await evalJS(snap), null, 1));

  console.log('STEP 1 click hero Watered');
  console.log(JSON.stringify(await evalJS(`(() => { document.querySelector('.care--hero .btn--done').click(); return 'clicked'; })()`)));
  await delay(250);
  console.log(JSON.stringify(await evalJS(snap), null, 1));

  console.log('STEP 2 undo via toast');
  console.log(JSON.stringify(await evalJS(`(() => { document.querySelector('#toast-undo').click(); return 'clicked'; })()`)));
  await delay(250);
  console.log(JSON.stringify(await evalJS(snap), null, 1));

  console.log('STEP 3 snooze Frida via card');
  console.log(JSON.stringify(await evalJS(`(() => { const li = document.querySelector('.care--hero'); li.querySelector('[data-action="snooze"]').click(); return 'clicked'; })()`)));
  await delay(250);
  console.log(JSON.stringify(await evalJS(snap), null, 1));

  console.log('STEP 4 complete all remaining');
  for (let i = 0; i < 4; i++) {
    const r = await evalJS(`(() => { const b = document.querySelector('#care-list .care .btn--done'); if (!b) return 'none'; const name = b.closest('.care').querySelector('.care-name button').textContent; b.click(); return name; })()`);
    await delay(120);
    console.log('clicked', r);
  }
  await delay(300);
  console.log(JSON.stringify(await evalJS(snap), null, 1));
  console.log('errors', JSON.stringify(errs.slice(0,4).map(e=>e.params?.entry?.text || e.params?.exceptionDetails?.text)));
  ws.close(); process.exit(0);
};
setTimeout(() => { console.error('timeout'); process.exit(1); }, 20000);
EOF
